11	func (h *handler) handleExportCSV(w http.ResponseWriter, r *http.Request) {
12		tenantID := tenantFromCtx(r)
13	
14		days := 30
15		if d := r.URL.Query().Get("days"); d != "" {
16			if parsed, err := strconv.Atoi(d); err == nil && parsed > 0 && parsed <= 365 {
17				days = parsed
18			}
19		}
20	
21		project := r.URL.Query().Get("project")
22	
23		rows, err := h.store.GetExportData(r.Context(), tenantID, days, project)
24		if err != nil {
25			h.logger.Error("export query failed", "error", err)
26			http.Error(w, "query failed", http.StatusInternalServerError)
27			return
28		}
29	
30		filename := fmt.Sprintf("codeflow-export-%s.csv", time.Now().Format("2006-01-02"))
31		w.Header().Set("Content-Type", "text/csv")
32		w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=%q", filename))
33	
34		fmt.Fprintln(w, "date,project,command,event_type,input_tokens,output_tokens,tokens_saved,filter_name")
35		for _, row := range rows {
36			fmt.Fprintf(w, "%s,%s,%s,%s,%d,%d,%d,%s\n",
37				row.Date, csvQuote(row.Project), csvQuote(row.Command), row.EventType,
38				row.InputTokens, row.OutputTokens, row.TokensSaved, csvQuote(row.FilterName),
39			)
40		}
41	}
