43	func (h *handler) handleROISummary(w http.ResponseWriter, r *http.Request) {
44		tenantID := tenantFromCtx(r)
45	
46		days := 90
47		if d := r.URL.Query().Get("days"); d != "" {
48			if parsed, err := strconv.Atoi(d); err == nil && parsed > 0 && parsed <= 365 {
49				days = parsed
50			}
51		}
52	
53		summary, err := h.store.GetROISummary(r.Context(), tenantID, days)
54		if err != nil {
55			h.logger.Error("roi summary query failed", "error", err)
56			http.Error(w, "query failed", http.StatusInternalServerError)
57			return
58		}
59	
60		w.Header().Set("Content-Type", "application/json")
61		json.NewEncoder(w).Encode(summary)
62	}
63	
64	func csvQuote(s string) string {
65		if len(s) == 0 {
66			return ""
67		}
68		needsQuote := false
69		for _, c := range s {
70			if c == ',' || c == '"' || c == '\n' || c == '\r' {
71				needsQuote = true
72				break
73			}
74		}
75		if !needsQuote {
76			return s
77		}
78		quoted := "\""
79		for _, c := range s {
80			if c == '"' {
81				quoted += "\"\""
82			} else {
83				quoted += string(c)
84			}
85		}
86		return quoted + "\""
87	}
