47	func detectRedundantCommands(s SessionEvents) []Finding {
48		type cmdKey struct {
49			command     string
50			contentHash string
51		}
52		counts := make(map[cmdKey]int)
53		tokens := make(map[cmdKey]uint64)
54	
55		for _, e := range s.Events {
56			if e.ContentHash == "" {
57				continue
58			}
59			k := cmdKey{command: e.Command, contentHash: e.ContentHash}
60			counts[k]++
61			tokens[k] = e.InputTokens
62		}
63	
64		var findings []Finding
65		for k, count := range counts {
66			if count < 2 {
67				continue
68			}
69			redundant := count - 1
70			wasted := tokens[k] * uint64(redundant)
71			findings = append(findings, Finding{
72				TenantID:     s.TenantID,
73				SessionID:    s.SessionID,
74				ProjectDir:   s.ProjectDir,
75				PatternType:  "redundant_command",
76				Command:      k.command,
77				Occurrences:  count,
78				TokensWasted: wasted,
79				Suggestion:   fmt.Sprintf("'%s' ran %dx with identical output — %d runs were redundant (%d tokens wasted)", k.command, count, redundant, wasted),
80				Timestamp:    time.Now(),
81			})
82		}
83		return findings
84	}
