98			k := readKey{command: e.Command}
99			readCounts[k]++
100			readTokens[k] = e.InputTokens
101		}
102	
103		var findings []Finding
104		for k, count := range readCounts {
105			if count < 3 {
106				continue
107			}
108			redundant := count - 1
109			wasted := readTokens[k] * uint64(redundant)
110			findings = append(findings, Finding{
111				TenantID:     s.TenantID,
112				SessionID:    s.SessionID,
113				ProjectDir:   s.ProjectDir,
114				PatternType:  "re_read_waste",
115				Command:      k.command,
116				Occurrences:  count,
117				TokensWasted: wasted,
118				Suggestion:   fmt.Sprintf("'%s' re-read %dx in one session — consider caching or splitting large files", k.command, count),
119				Timestamp:    time.Now(),
120			})
121		}
