135			tokens uint64
136		}
137		streaks := make(map[string]*streak)
138	
139		var findings []Finding
140		for _, e := range s.Events {
141			if !buildCmds[e.Command] {
142				for cmd, st := range streaks {
143					if st.count >= 3 {
144						findings = append(findings, buildLoopFinding(s, cmd, st.count, st.tokens))
145					}
146				}
147				streaks = make(map[string]*streak)
148				continue
149			}
150	
151			st, ok := streaks[e.Command]
152			if !ok {
153				st = &streak{}
154				streaks[e.Command] = st
155			}
156			st.count++
157			st.tokens += e.InputTokens
158		}
159	
160		for cmd, st := range streaks {
161			if st.count >= 3 {
162				findings = append(findings, buildLoopFinding(s, cmd, st.count, st.tokens))
163			}
164		}
165	
166		return findings
167	}
