package api

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestHandleExportCSV_DefaultDays(t *testing.T) {
	store := newFakeStorage()
	router := newTestRouter(store)

	req := httptest.NewRequest("GET", "/v1/export/csv", nil)
	req.Header.Set("X-Tenant-ID", "tenant-1")

	w := httptest.NewRecorder()
	router.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d: %s", w.Code, w.Body.String())
	}

	ct := w.Header().Get("Content-Type")
	if !strings.HasPrefix(ct, "text/csv") {
		t.Fatalf("expected text/csv content-type, got %q", ct)
	}

	cd := w.Header().Get("Content-Disposition")
	if !strings.Contains(cd, "attachment") {
		t.Fatalf("expected attachment content-disposition, got %q", cd)
	}
	if !strings.Contains(cd, "codeflow-export-") {
		t.Fatalf("expected filename in content-disposition, got %q", cd)
	}

	body := w.Body.String()
	if !strings.HasPrefix(body, "date,project,command,event_type,") {
		t.Fatalf("expected CSV header row, got: %q", body)
	}
}

func TestHandleExportCSV_CustomDays(t *testing.T) {
	store := newFakeStorage()
	router := newTestRouter(store)

	req := httptest.NewRequest("GET", "/v1/export/csv?days=7", nil)
	req.Header.Set("X-Tenant-ID", "tenant-1")

	w := httptest.NewRecorder()
	router.ServeHTTP(w, req)

