func TestHandleROISummary_DefaultDays(t *testing.T) {
	store := newFakeStorage()
	router := newTestRouter(store)

	req := httptest.NewRequest("GET", "/v1/roi", nil)
	req.Header.Set("X-Tenant-ID", "tenant-1")

