func TestHandleBillingStatus_ValidTenant(t *testing.T) {
	store := newFakeStorage()
	router := newTestRouter(store)

	req := httptest.NewRequest("GET", "/v1/billing/status", nil)
	req.Header.Set("X-Tenant-ID", "tenant-abc")

	w := httptest.NewRecorder()
	router.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d: %s", w.Code, w.Body.String())
	}

	ct := w.Header().Get("Content-Type")
	if !strings.HasPrefix(ct, "application/json") {
		t.Fatalf("expected application/json, got %q", ct)
	}

	var resp map[string]any
	if err := json.NewDecoder(w.Body).Decode(&resp); err != nil {
		t.Fatalf("failed to decode JSON response: %v", err)
	}

	if _, ok := resp["plan"]; !ok {
		t.Fatal("expected 'plan' field in billing status response")
	}
	if _, ok := resp["status"]; !ok {
		t.Fatal("expected 'status' field in billing status response")
	}

	// fakeStorage returns plan="free", status="active"
	if plan, _ := resp["plan"].(string); plan != "free" {
		t.Fatalf("expected plan='free', got %q", plan)
	}
	if status, _ := resp["status"].(string); status != "active" {
		t.Fatalf("expected status='active', got %q", status)
	}
}

func TestHandleStripeWebhook_MissingSecret_Returns503(t *testing.T) {
	os.Unsetenv("STRIPE_WEBHOOK_SECRET")

	store := newFakeStorage()
	router := newTestRouter(store)

	// webhook route is not behind auth middleware, no X-Tenant-ID needed
	req := httptest.NewRequest("POST", "/v1/billing/webhook", strings.NewReader("{}"))
	req.Header.Set("Content-Type", "application/json")

	w := httptest.NewRecorder()
	router.ServeHTTP(w, req)

	if w.Code != http.StatusServiceUnavailable {
		t.Fatalf("expected 503, got %d: %s", w.Code, w.Body.String())
	}
}

func TestHandleStripeWebhook_InvalidSignature_Returns400(t *testing.T) {
	os.Setenv("STRIPE_WEBHOOK_SECRET", "whsec_test_secret")
	defer os.Unsetenv("STRIPE_WEBHOOK_SECRET")

	store := newFakeStorage()
	router := newTestRouter(store)

	req := httptest.NewRequest("POST", "/v1/billing/webhook", strings.NewReader(`{"type":"checkout.session.completed"}`))
	req.Header.Set("Content-Type", "application/json")
	// Missing or invalid Stripe-Signature header — webhook.ConstructEvent will reject it
	req.Header.Set("Stripe-Signature", "t=invalid,v1=invalidsig")

	w := httptest.NewRecorder()
	router.ServeHTTP(w, req)

	if w.Code != http.StatusBadRequest {
		t.Fatalf("expected 400 for invalid signature, got %d: %s", w.Code, w.Body.String())
	}
}
